local _bx = (bit32 and bit32.bxor) or function(a, b)
	local r, p = 0, 1
	while a > 0 or b > 0 do
		local x, y = a % 2, b % 2
		if x ~= y then
			r = r + p
		end
		a, b, p = (a - x) / 2, (b - y) / 2, p * 2
	end
	return r
end
local _B = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
local _INV = {}
for i = 1, #_B do
	_INV[_B:sub(i, i)] = i - 1
end
local function _b64d(s)
	local out, n, buf, bits = {}, 0, 0, 0
	for i = 1, #s do
		local ch = s:sub(i, i)
		local v = _INV[ch]
		if v then
			buf = buf * 64 + v
			bits = bits + 6
			if bits >= 8 then
				bits = bits - 8
				n = n + 1
				out[n] = string.char(math.floor(buf / (2 ^ bits)) % 256)
				buf = buf % (2 ^ bits)
			end
		end
	end
	return table.concat(out)
end
